use serde_json::{json,Value};use std::{fs,path::{Path,PathBuf},os::windows::fs::MetadataExt};
pub fn recycle_info()->Result<Value,String>{use windows_sys::Win32::UI::Shell::{SHQUERYRBINFO,SHQueryRecycleBinW};let mut info=SHQUERYRBINFO{cbSize:std::mem::size_of::<SHQUERYRBINFO>() as u32,i64Size:0,i64NumItems:0};let result=unsafe{SHQueryRecycleBinW(std::ptr::null(),&mut info)};if result<0{return Err(format!("A lixeira não está disponível: HRESULT {result:#x}"))}Ok(json!({"bytes":info.i64Size,"items":info.i64NumItems,"reversible":false}))}
pub fn empty_recycle()->Result<Value,String>{let result=unsafe{windows_sys::Win32::UI::Shell::SHEmptyRecycleBinW(std::ptr::null_mut(),std::ptr::null(),4)};if result==0{return Ok(json!({"status":"completed","remaining":recycle_info()?}))}if result==0x80004004u32 as i32{return Ok(json!({"status":"cancelled"}))}Err(format!("A lixeira não foi esvaziada: HRESULT {result:#x}"))}
pub fn large_files(root:&str,threshold_mb:u64)->Result<Value,String>{let original=Path::new(root);if !original.is_absolute()||root.starts_with("\\\\")||!(100..=10000).contains(&threshold_mb){return Err("Escolha uma pasta local absoluta e um limite de 100 a 10000 MB".into())}let metadata=fs::symlink_metadata(original).map_err(|e|e.to_string())?;if !metadata.is_dir()||metadata.file_attributes()&0x400!=0{return Err("Pasta irregular ou reparse point".into())}let root=original.canonicalize().map_err(|e|e.to_string())?;if root.parent().is_none(){return Err("Escolha uma pasta específica; não é analisada uma unidade inteira".into())}if let Some(system)=std::env::var_os("SystemRoot"){if root.starts_with(PathBuf::from(system).canonicalize().map_err(|e|e.to_string())?){return Err("As pastas do Windows estão protegidas".into())}}scan_large(&root,threshold_mb*1024*1024)}
fn scan_large(root:&Path,threshold:u64)->Result<Value,String>{let mut stack=vec![(root.to_path_buf(),0u8)];let mut rows=Vec::new();let mut visited=0;let mut skipped=0;while let Some((folder,depth))=stack.pop(){if visited>=50000||rows.len()>=1000{break}let entries=match fs::read_dir(folder){Ok(e)=>e,Err(_)=>{skipped+=1;continue}};for entry in entries{if visited>=50000||rows.len()>=1000{break}visited+=1;let entry=match entry{Ok(e)=>e,Err(_)=>{skipped+=1;continue}};let path=entry.path();let m=match fs::symlink_metadata(&path){Ok(m)=>m,Err(_)=>{skipped+=1;continue}};if m.file_attributes()&0x400!=0{skipped+=1;continue}if m.is_dir(){if depth<8{stack.push((path,depth+1));}else{skipped+=1}}else if m.is_file()&&m.len()>=threshold{rows.push(json!({"path":path.to_string_lossy(),"bytes":m.len(),"category":"Ficheiro grande — apenas leitura"}));}}}rows.sort_by_key(|r|std::cmp::Reverse(r["bytes"].as_u64().unwrap_or(0)));Ok(json!({"files":rows,"visited":visited,"skipped":skipped,"limited":visited>=50000||rows.len()>=1000,"deletion_supported":false}))}
#[cfg(test)]mod tests{use super::*;#[test]fn scanner_only_reads_fixture(){let temp=tempfile::tempdir().unwrap();let path=temp.path().join("personal.save");fs::write(&path,[1,2,3,4]).unwrap();let result=scan_large(temp.path(),3).unwrap();assert_eq!(result["files"].as_array().unwrap().len(),1);assert!(path.exists());assert_eq!(result["deletion_supported"],false);}#[test]fn unbounded_roots_are_rejected(){assert!(large_files("relative",100).is_err());assert!(large_files("\\\\server\\share",100).is_err());}}
